import{c as t,Q as i,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"300 Claude Fable 5 Prompts That Replace Hours of Manual Work Every Single Day","description":"","frontmatter":{"url":"https://x.com/cyrilxbt/status/2065984221756219807","title":"300 Claude Fable 5 Prompts That Replace Hours of Manual Work Every Single Day","author":"cyrilXBT","archived":"2026-06-14T00:00:00.000Z","handle":"@cyrilXBT","published":"2026-06-14T00:00:00.000Z","stats":"125 likes · 18 retweets · 145 bookmarks · 12467 views","tags":["claude-fable5","prompts","prompt-engineering","agentic","workflow","productivity"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-14-@cyrilXBT-219807.md","filePath":"research/tweets/2026-06-14-@cyrilXBT-219807.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-06-14-@cyrilXBT-219807.md"};function s(l,e,r,h,d,p){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="_300-claude-fable-5-prompts-that-replace-hours-of-manual-work-every-single-day-—-cyrilxbt" tabindex="-1">300 Claude Fable 5 Prompts That Replace Hours of Manual Work Every Single Day — @cyrilXBT <a class="header-anchor" href="#_300-claude-fable-5-prompts-that-replace-hours-of-manual-work-every-single-day-—-cyrilxbt" aria-label="Permalink to &quot;300 Claude Fable 5 Prompts That Replace Hours of Manual Work Every Single Day — @cyrilXBT&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/cyrilxbt/status/2065984221756219807" target="_blank" rel="noreferrer">https://x.com/cyrilxbt/status/2065984221756219807</a><strong>作者</strong>：cyrilXBT（@cyrilXBT） <strong>發布日期</strong>：2026-06-14 <strong>收錄日期</strong>：2026-06-14 <strong>類型</strong>：Twitter Article <strong>統計</strong>：125 likes · 18 retweets · 145 bookmarks · 12467 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Most people use Claude Fable 5 the same way they used every previous model. They open a chat. They type a question. They get an answer. They close the tab. That approach with Fable 5 is like using a Formula 1 car to drive to the grocery store. Fable 5 is a Mythos-class model designed for long-running, complex, multi-step work that previous models could not handle reliably. It has a 1 million token context window. It can operate autonomously for days. It admits when it fails. It reasons at a depth that changes what is possible in a single session. The prompts in this article are built for that capability level. Not generic prompts that work on any model. Prompts engineered for what Fable 5 specifically can do that nothing before it could do as reliably. Organized into ten categories. Thirty prompts per category. Three hundred total.</p><h2 id="category-1-deep-research-and-synthesis-30-prompts" tabindex="-1">Category 1: Deep Research and Synthesis (30 Prompts) <a class="header-anchor" href="#category-1-deep-research-and-synthesis-30-prompts" aria-label="Permalink to &quot;Category 1: Deep Research and Synthesis (30 Prompts)&quot;">​</a></h2><p>These prompts leverage Fable 5&#39;s ability to hold massive context and reason across it simultaneously.</p><ol><li><p>Read everything I&#39;ve given you and produce a synthesis that identifies the three claims all sources agree on, the three claims they contradict each other on, and the single most important thing none of them address.</p></li><li><p>You are a senior research analyst. Read this corpus and tell me what a smart person who read all of it would believe that someone who read only the headlines would miss entirely.</p></li><li><p>I&#39;m researching [TOPIC]. Read these sources and tell me: what does the evidence clearly support, what is genuinely contested, and what questions would I need to answer to resolve the contested parts?</p></li><li><p>Read this research and steelman the position I disagree with most strongly. Give me the best version of the argument against my current position using only the evidence provided.</p></li><li><p>Treat this collection of documents as a dataset. What patterns appear across them that would be invisible reading any individual document alone?</p></li><li><p>Read everything and identify the assumption that, if false, would invalidate the most conclusions. Explain exactly why that assumption is load-bearing.</p></li><li><p>I need to brief someone who has 10 minutes. Read this entire corpus and give me the five things they absolutely cannot afford not to know. Nothing else.</p></li><li><p>Read these sources and map the disagreements. Not surface disagreements. The underlying disagreements about values, methodology, or definitions that are driving the surface ones.</p></li><li><p>You are a skeptic. Read this research and find the weakest link in the chain of reasoning. The place where one challenged assumption makes the whole argument less convincing.</p></li><li><p>Read this and produce a one-page briefing written for a decision-maker who needs to act on it today. Include what they should do, what they should watch for, and what they should ignore.</p></li><li><p>Identify every claim in this document that is stated as fact but is actually an assumption. List each one with why it qualifies as an assumption rather than established fact.</p></li><li><p>Read this corpus and tell me what a journalist with no prior knowledge of this field would get wrong if they reported on it based on this material alone.</p></li><li><p>I&#39;m trying to understand [TOPIC]. Read these sources and explain it to me the way a domain expert would explain it to an intelligent non-specialist. No jargon without definition.</p></li><li><p>Read everything and identify the three most counterintuitive findings. Things that contradict what most people in this space believe. Cite the specific source for each.</p></li><li><p>Produce a research brief that distinguishes between what we know, what we think we know, and what we are guessing. Label every claim with one of those three categories.</p></li><li><p>Read this and produce a devil&#39;s advocate brief. The strongest possible case against the position these sources collectively argue for.</p></li><li><p>What would change about the conclusions in this research if the most important data point were wrong? Walk me through the cascade.</p></li><li><p>Read these documents and identify every place where correlation is presented as causation. Cite each instance specifically.</p></li><li><p>Synthesize this research into a framework I can apply to similar situations in the future. Not a summary of what it says. A tool I can use.</p></li><li><p>Read this corpus and tell me what questions it raises that it doesn&#39;t answer. Rank them by importance to someone trying to make a decision based on this material.</p></li><li><p>I need to cite this research accurately. Read it and give me the five strongest claims that are well-supported enough to cite with confidence and five claims I should avoid citing because the support is weak.</p></li><li><p>Read everything and produce a gap analysis. What does someone who wants to understand this topic fully still need to research after reading all of this?</p></li><li><p>Treat this as a first draft of a research brief. Read it and tell me what a rigorous editor would push back on, demand evidence for, or cut entirely.</p></li><li><p>Read this corpus and identify the expert consensus, the minority position, and the fringe position. Be specific about where each lives in the source material.</p></li><li><p>I&#39;m about to make a decision based on this research. Read it and tell me what I&#39;m missing that I should know before deciding.</p></li><li><p>Read these documents and extract every specific data point with its source and date. Flag any data point that is more than three years old.</p></li><li><p>Synthesize this into a competitive intelligence brief. What does someone who reads this understand about the competitive landscape that someone who doesn&#39;t read it misses?</p></li><li><p>Read this and produce a timeline of how thinking on this topic has evolved based on publication dates of the sources.</p></li><li><p>What would Nassim Taleb say about the risk assessment in this research? Apply his framework to the claims made.</p></li><li><p>Read this corpus and produce the most honest one-paragraph summary possible. No spin. No framing. Just what the evidence actually shows.</p></li></ol><h2 id="category-2-writing-and-content-production-30-prompts" tabindex="-1">Category 2: Writing and Content Production (30 Prompts) <a class="header-anchor" href="#category-2-writing-and-content-production-30-prompts" aria-label="Permalink to &quot;Category 2: Writing and Content Production (30 Prompts)&quot;">​</a></h2><ol start="31"><li><p>Write this piece in my voice. Before drafting, tell me what you understand my voice to be based on the examples I&#39;ve provided. Then write. Then tell me where you were uncertain.</p></li><li><p>I&#39;m writing about [TOPIC]. Give me the angle that nobody in this space has taken that is also the most honest framing of what&#39;s actually happening.</p></li><li><p>Write a first draft. Then write a second draft that challenges every claim in the first draft. Then give me a third draft that incorporates what survives the challenge.</p></li><li><p>Take this rough outline and identify the section that is doing the most work carrying the argument. Develop that section fully before touching anything else.</p></li><li><p>Write the opening paragraph ten different ways. Each one should use a completely different approach to earning the reader&#39;s attention. Label each approach.</p></li><li><p>I have a piece that works but doesn&#39;t land. Read it and diagnose exactly what&#39;s preventing it from landing. Then rewrite the specific parts that are failing.</p></li><li><p>Write this article as if the reader is skeptical of the main claim from the first sentence. Every paragraph should earn the next one.</p></li><li><p>Take this draft and cut it by 40% without losing the argument. Then tell me what you cut and why each cut was right.</p></li><li><p>I need to write about [TOPIC] for an audience that thinks they already understand it. Write something that gives them genuine new understanding without making them feel patronized.</p></li><li><p>Write the version of this piece that would get the most pushback and the version that would get the most agreement. Then write the version that is most accurate regardless of reaction.</p></li><li><p>Take my rough notes on [TOPIC] and identify the strongest argument hiding in them. Build that argument into a complete piece.</p></li><li><p>Write three different introductions for this piece. One that leads with the problem. One that leads with the stakes. One that leads with a counterintuitive claim. Tell me which you would choose and why.</p></li><li><p>Read this draft and identify every sentence that is doing no work. Cut them. Then identify every sentence that is doing the wrong work and rewrite them.</p></li><li><p>Write this in the style of [PUBLICATION] without copying their tone. Match their standard for evidence and specificity while keeping my voice.</p></li><li><p>I need a conclusion that doesn&#39;t summarize. Write an ending that leaves the reader with something they didn&#39;t have before they started reading.</p></li><li><p>Take this piece and identify the single claim that the rest of the piece depends on. Make sure that claim is stated clearly, early, and supported better than any other.</p></li><li><p>Write the most useful version of this piece for someone who will read it once and needs to act on it immediately.</p></li><li><p>Read this and identify where I&#39;m hedging unnecessarily. Rewrite those sections with the conviction the argument actually warrants.</p></li><li><p>Write a piece about [TOPIC] that would make someone who disagrees with me feel their position was understood before I made my case.</p></li><li><p>Take this outline and tell me which sections are load-bearing and which are padding. Cut the padding. Strengthen the load-bearing sections.</p></li><li><p>Write this piece backwards. Start with the conclusion and work backwards to the evidence. Sometimes that&#39;s the right structure.</p></li><li><p>I need to write about something complicated without oversimplifying it. Write the version that is genuinely accurate and still readable by a non-specialist.</p></li><li><p>Take my voice and this topic and write the piece I would write if I had spent three months researching it rather than three hours.</p></li><li><p>Write a draft. Then read it as a hostile editor and mark every place where a smart skeptic would stop reading. Fix those places.</p></li><li><p>I need a lede that makes this piece impossible to put down. Write five options. Each one should create a different type of tension.</p></li><li><p>Read this draft and tell me the one thing I&#39;m afraid to say that I should say. Then write the version that says it.</p></li><li><p>Write the version of this piece that will be most shared. Not the most viral. The most genuinely useful to someone who shares it with someone they care about.</p></li><li><p>Take this topic and write the piece that will be cited as a reference five years from now. What makes something durable rather than timely?</p></li><li><p>Write this in under 500 words without losing the argument. Then write it in under 200 words without losing the core claim.</p></li><li><p>I have too much to say and not enough structure. Read my notes and build the architecture before writing a word.</p></li></ol><h2 id="category-3-business-strategy-and-analysis-30-prompts" tabindex="-1">Category 3: Business Strategy and Analysis (30 Prompts) <a class="header-anchor" href="#category-3-business-strategy-and-analysis-30-prompts" aria-label="Permalink to &quot;Category 3: Business Strategy and Analysis (30 Prompts)&quot;">​</a></h2><ol start="61"><li><p>Read this business plan and tell me the three assumptions that, if wrong, make everything else irrelevant. Rank them by probability of being wrong.</p></li><li><p>I&#39;m deciding between [OPTION A] and [OPTION B]. Give me the strongest case for each before giving me your recommendation. Then tell me what information would change your recommendation.</p></li><li><p>Analyze this market and tell me what a well-capitalized competitor who understood it deeply would do in the next 18 months.</p></li><li><p>Read this business and identify the single constraint limiting growth more than anything else. The one thing that, if removed, would change everything.</p></li><li><p>I need to pressure-test this strategy. Play the role of the smartest competitor in this market and tell me exactly how you would respond to what I&#39;m planning.</p></li><li><p>Read this P&amp;L and tell me what a CFO would find concerning that the founder is probably not worried enough about.</p></li><li><p>I&#39;m building in [MARKET]. Tell me the three incumbents most threatened by what I&#39;m building and how each would likely respond.</p></li><li><p>Analyze this company&#39;s positioning and tell me the gap they are leaving open that a well-positioned competitor could exploit.</p></li><li><p>Read this strategy document and identify every place where we are optimizing for a metric that doesn&#39;t actually predict what we care about.</p></li><li><p>I have a strategic decision to make. Walk me through the second and third-order effects of each option before I decide.</p></li><li><p>Read this competitive analysis and tell me what we got wrong about how our competitors think about their own business.</p></li><li><p>I need to prioritize. Read these ten initiatives and rank them by expected value times probability of success. Show your reasoning.</p></li><li><p>Analyze this market entry opportunity and tell me the three most likely reasons it fails within 24 months.</p></li><li><p>Read this and identify every place where we are confusing activity with progress. Where are we busy doing things that don&#39;t move the needle?</p></li><li><p>I need to make a build versus buy versus partner decision on [CAPABILITY]. Walk me through the full analysis before recommending.</p></li><li><p>Read this business and identify the single metric that predicts success better than any other. Explain why everything else is downstream of it.</p></li><li><p>I&#39;m about to enter a pricing negotiation. Read this context and give me the five moves I should prepare for and how to respond to each.</p></li><li><p>Analyze this company&#39;s strengths and tell me which ones are actually defensible and which ones look like advantages but will erode.</p></li><li><p>I need to tell a story about this business that is true, compelling, and that our best customers immediately recognize as accurate. Write it.</p></li><li><p>Read this strategy and identify every assumption we are making about customer behavior that we haven&#39;t validated.</p></li><li><p>I&#39;m three years into building this and I need fresh eyes. Read everything and tell me what you see that I probably can&#39;t see anymore because I&#39;m too close to it.</p></li><li><p>Analyze this partnership opportunity and tell me the five ways it could go wrong that neither party is currently discussing.</p></li><li><p>I need to make this business more defensible. Read it and identify the three moats I could build that would be genuinely hard to replicate.</p></li><li><p>Read this growth strategy and tell me what we&#39;re assuming about retention that our acquisition numbers might be hiding.</p></li><li><p>I&#39;m building a board presentation. Read this material and tell me the three questions a good board member will ask that we are not currently prepared to answer.</p></li><li><p>Analyze this market and tell me who the real customer is versus who we think the customer is.</p></li><li><p>Read this and identify where we have a feature versus where we have a product versus where we have a business.</p></li><li><p>I need to allocate budget across these initiatives. Read them and tell me where the highest leverage dollar is and where we are most likely wasting money.</p></li><li><p>Analyze this competitive response and tell me whether it reflects fear or strategy. The distinction matters for how we respond.</p></li><li><p>Read this business model and identify the unit economics assumption that most needs to be validated before we scale.</p></li></ol><h2 id="category-4-code-and-technical-work-30-prompts" tabindex="-1">Category 4: Code and Technical Work (30 Prompts) <a class="header-anchor" href="#category-4-code-and-technical-work-30-prompts" aria-label="Permalink to &quot;Category 4: Code and Technical Work (30 Prompts)&quot;">​</a></h2><ol start="91"><li><p>Read this entire codebase and tell me the three architectural decisions that will be most painful to reverse as we scale.</p></li><li><p>I need to refactor this. Before touching anything, map the dependencies and tell me the order that minimizes risk.</p></li><li><p>Read this code and identify every place where we have technical debt that is actively slowing down new development.</p></li><li><p>Write this function then review it as a senior engineer who cares about edge cases. Then fix what the review finds.</p></li><li><p>I need to debug this. Walk me through your reasoning as you diagnose it rather than just giving me the answer.</p></li><li><p>Read this codebase and write documentation that would let a new engineer be productive in their first week.</p></li><li><p>Review this code for security vulnerabilities. For each one found, explain the attack vector and the fix.</p></li><li><p>I need to optimize this for performance. Profile it first, identify the bottleneck, then optimize only what matters.</p></li><li><p>Write tests for this code. Focus on the edge cases that could cause production failures, not the happy path.</p></li><li><p>Read this architecture and tell me what breaks first when traffic is ten times current volume.</p></li><li><p>I&#39;m starting a new project. Read my requirements and recommend the technology stack with honest tradeoffs for each choice.</p></li><li><p>Review this pull request as a senior engineer who cares about maintainability above cleverness.</p></li><li><p>Read this code and tell me what the original developer was thinking, where they made assumptions, and where those assumptions might be wrong.</p></li><li><p>I need to migrate this to [NEW TECHNOLOGY]. Read the current implementation and produce a migration plan that minimizes downtime.</p></li><li><p>Write this API. Then write the documentation. Then write the tests. In that order.</p></li><li><p>Read this error log and tell me what&#39;s happening in plain English before giving me the fix.</p></li><li><p>I need code review. Read this and tell me everything a senior engineer would say in a code review. Don&#39;t hold back.</p></li><li><p>Build this feature. Before writing code, tell me the design decision you&#39;re making and why. Then implement it.</p></li><li><p>Read this codebase and identify the functions that are doing more than one thing. Split them.</p></li><li><p>I need to handle this edge case. Read the surrounding code and implement the fix in a way that fits the existing patterns.</p></li><li><p>Write the simplest possible implementation of this feature. Then tell me what I&#39;d need to add to make it production-ready.</p></li><li><p>Read this code and tell me where we are relying on undefined behavior or implementation details that could change.</p></li><li><p>I&#39;m doing a security audit. Read this codebase and prioritize the vulnerabilities by severity and exploitability.</p></li><li><p>Write this in the pattern that will be easiest to modify in six months when requirements change.</p></li><li><p>Read this and tell me everywhere we have a magic number that should be a named constant.</p></li><li><p>I need to scale this database query. Read the schema and the query, explain why it&#39;s slow, and fix it.</p></li><li><p>Review this for accessibility. Tell me what a user with [SPECIFIC LIMITATION] would experience and fix the issues.</p></li><li><p>Read this code and write a runbook for the on-call engineer when this service fails.</p></li><li><p>I need to implement [FEATURE]. Read the existing codebase first and implement it in a way that fits the existing architecture rather than introducing new patterns.</p></li><li><p>Read this and tell me which parts I should delete rather than maintain.</p></li></ol><h2 id="category-5-decision-support-30-prompts" tabindex="-1">Category 5: Decision Support (30 Prompts) <a class="header-anchor" href="#category-5-decision-support-30-prompts" aria-label="Permalink to &quot;Category 5: Decision Support (30 Prompts)&quot;">​</a></h2><ol start="121"><li><p>I&#39;m deciding [DECISION]. Give me the frame I&#39;m not seeing because I&#39;m too close to it.</p></li><li><p>Walk me through the pre-mortem for this decision. It&#39;s two years from now and it failed. What happened?</p></li><li><p>I&#39;ve made this decision emotionally. Now give me the rational case for the opposite choice so I can decide properly.</p></li><li><p>What am I optimizing for with this decision that I haven&#39;t stated explicitly? Name it and tell me if that&#39;s actually what I should be optimizing for.</p></li><li><p>I have all the information I think I need to decide. What am I missing that I don&#39;t know I&#39;m missing?</p></li><li><p>Give me the decision tree for this choice. Every branch. Every node. Every probability I should assign.</p></li><li><p>I&#39;m about to make a reversible decision as if it&#39;s irreversible. Tell me what that costs me.</p></li><li><p>I&#39;m about to make an irreversible decision as if it&#39;s reversible. Tell me what that costs me.</p></li><li><p>What would I decide if I knew I had to live with the consequences for ten years?</p></li><li><p>Tell me the decision that I&#39;m avoiding making by making this one.</p></li><li><p>I need to make this decision with incomplete information. What&#39;s the minimum I need to know to decide responsibly?</p></li><li><p>Give me the base rate for this type of decision. How often do people who make this choice in these circumstances get the outcome they&#39;re hoping for?</p></li><li><p>I think the risk here is [X]. What risk am I underweighting?</p></li><li><p>Walk me through the second and third-order effects of this decision that I&#39;m probably not thinking about.</p></li><li><p>What does this decision signal to the people watching me make it?</p></li><li><p>I&#39;m deciding between fast and right. Help me figure out which one actually matters more here.</p></li><li><p>What would I need to believe for the option I&#39;m leaning against to be the right choice?</p></li><li><p>Give me the version of this decision that I would be proud to explain to someone I respect.</p></li><li><p>I&#39;ve been going back and forth on this. What does that tell you about what I actually value?</p></li><li><p>What&#39;s the cost of not deciding right now?</p></li><li><p>I&#39;m treating this as a binary choice. What&#39;s the third option I&#39;m missing?</p></li><li><p>Give me the decision that optimizes for optionality rather than outcome.</p></li><li><p>What would a person who has made this decision successfully ten times know that I don&#39;t?</p></li><li><p>I need to make this decision without being able to explain it fully. What&#39;s the simplest justification that&#39;s also honest?</p></li><li><p>Walk me through how I&#39;ll feel about this decision in a week, a month, and a year.</p></li><li><p>What&#39;s the asymmetry here? How bad is the downside versus how good is the upside?</p></li><li><p>I&#39;m deciding this under time pressure. Tell me if the time pressure is real or manufactured.</p></li><li><p>What would the person I want to become decide?</p></li><li><p>Give me one reason to decide now and one reason to wait. Then tell me which one is right.</p></li><li><p>What am I afraid of that I haven&#39;t said?</p></li></ol><h2 id="category-6-communication-and-persuasion-30-prompts" tabindex="-1">Category 6: Communication and Persuasion (30 Prompts) <a class="header-anchor" href="#category-6-communication-and-persuasion-30-prompts" aria-label="Permalink to &quot;Category 6: Communication and Persuasion (30 Prompts)&quot;">​</a></h2><ol start="151"><li><p>I need to persuade [PERSON] to [ACTION]. Write the message that starts from where they are rather than where I want them to be.</p></li><li><p>Read this email and tell me how the recipient will feel after reading the first sentence, the third paragraph, and the close.</p></li><li><p>I need to say something difficult. Write the version that is honest without being unkind and direct without being brutal.</p></li><li><p>Write this message for someone who reads fast and decides in the first ten seconds.</p></li><li><p>I need to decline this without damaging the relationship. Write the no that keeps the door open.</p></li><li><p>Read this message I received and tell me what they&#39;re actually asking for beneath what they said.</p></li><li><p>I need to give feedback that will be heard rather than defended against. Write it so the other person can receive it.</p></li><li><p>Write the follow-up message for someone who hasn&#39;t responded in two weeks that doesn&#39;t sound desperate.</p></li><li><p>I need to make a request of someone more senior than me. Write the ask that respects their time and makes yes easy.</p></li><li><p>Read this message and tell me every assumption I&#39;m making about how the recipient will interpret it.</p></li><li><p>I need to communicate bad news. Write the message that is honest about what happened and clear about what happens next.</p></li><li><p>Write this pitch for someone who has heard a hundred pitches this week and is actively looking for reasons to say no.</p></li><li><p>I need to escalate this issue without damaging my relationship with the person I&#39;m escalating about.</p></li><li><p>Write the message that makes this complex thing simple without making it simplistic.</p></li><li><p>I need to apologize in a way that repairs rather than just acknowledges. Write it.</p></li><li><p>Read this thread and tell me where the miscommunication started and how to repair it.</p></li><li><p>Write the version of this proposal that makes the reader feel like they came up with the idea.</p></li><li><p>I need to say no to a good opportunity for the right reasons. Write the response that explains without over-explaining.</p></li><li><p>Write this announcement for the person who will be most skeptical of it.</p></li><li><p>I need to negotiate this. Write the opening position that gives me room to move while establishing what I actually need.</p></li><li><p>Read this and tell me the subtext. What is this person actually saying?</p></li><li><p>Write the response to this criticism that is neither defensive nor dismissive.</p></li><li><p>I need to align two people who disagree. Write the message that finds the common ground they don&#39;t know they share.</p></li><li><p>Write this update for an audience that includes people who will use anything negative to undermine the project.</p></li><li><p>I need to communicate uncertainty without losing confidence. Write the message that is honest about what we don&#39;t know while clear about what we do.</p></li><li><p>Write the version of this message that the recipient will forward to someone else because it&#39;s that useful.</p></li><li><p>I need to set a boundary professionally. Write it clearly without making it an ultimatum.</p></li><li><p>Read this and tell me what I should ask before I respond.</p></li><li><p>Write this cold outreach for someone who deletes cold outreach immediately.</p></li><li><p>I need to close this. Write the message that makes it easy for them to say yes right now.</p></li></ol><h2 id="category-7-learning-and-knowledge-development-30-prompts" tabindex="-1">Category 7: Learning and Knowledge Development (30 Prompts) <a class="header-anchor" href="#category-7-learning-and-knowledge-development-30-prompts" aria-label="Permalink to &quot;Category 7: Learning and Knowledge Development (30 Prompts)&quot;">​</a></h2><ol start="181"><li><p>Explain [CONCEPT] to me the way a world-class teacher would explain it to someone who is intelligent but has no background in this field.</p></li><li><p>I think I understand [CONCEPT]. Test me. Ask me questions that reveal whether I actually understand it or just know the vocabulary.</p></li><li><p>What&#39;s the thing about [TOPIC] that most people get wrong because they learned the simplified version?</p></li><li><p>Give me the mental model for [DOMAIN] that an expert uses that a beginner doesn&#39;t have.</p></li><li><p>I&#39;ve read a lot about [TOPIC]. What should I read next that will genuinely change how I think rather than just add more of what I already know?</p></li><li><p>Explain this to me using an analogy from [COMPLETELY DIFFERENT DOMAIN]. Make the analogy earn its place.</p></li><li><p>What are the three questions about [TOPIC] that separate people who really understand it from people who just know about it?</p></li><li><p>I&#39;m learning [SKILL]. What&#39;s the deliberate practice that produces the most improvement fastest?</p></li><li><p>Teach me the history of [IDEA] in a way that helps me understand why it took so long to figure out.</p></li><li><p>What would change about how I approach [TOPIC] if I understood it the way a genuine expert does?</p></li><li><p>Give me the curriculum for becoming genuinely good at [SKILL] in six months if I can dedicate two hours per day.</p></li><li><p>What&#39;s the thing about [FIELD] that took you the longest to understand and that everyone new to the field struggles with?</p></li><li><p>Explain the distinction between [CONCEPT A] and [CONCEPT B] in a way that makes it impossible to confuse them again.</p></li><li><p>What&#39;s the best argument against the thing I just told you I believe? Make it as strong as you can.</p></li><li><p>I need to learn enough about [TOPIC] to have a credible conversation with an expert. What do I need to know?</p></li><li><p>Give me the Feynman explanation of [CONCEPT]. Simple enough to explain to a ten-year-old without being wrong.</p></li><li><p>What are the five books that have most shaped thinking in [FIELD] and what&#39;s the core idea from each?</p></li><li><p>I understand the what of [TOPIC]. Help me understand the why at a deeper level.</p></li><li><p>What&#39;s the question about [TOPIC] that I should be asking but haven&#39;t thought to ask yet?</p></li><li><p>Teach me [CONCEPT] by starting with the problem it was invented to solve.</p></li><li><p>What&#39;s the thing about [FIELD] that is widely believed but wrong?</p></li><li><p>I need to build intuition for [DOMAIN] not just knowledge. What&#39;s the difference and how do I get it?</p></li><li><p>Give me the three most important experiments or case studies that shaped our understanding of [TOPIC].</p></li><li><p>What would I believe differently about [TOPIC] if I were an expert in it versus where I am now?</p></li><li><p>I&#39;ve hit a learning plateau with [SKILL]. Diagnose why and tell me how to break through.</p></li><li><p>Teach me this concept by showing me where it breaks down. The edge cases reveal more than the core.</p></li><li><p>What&#39;s the vocabulary I need to understand to think clearly about [TOPIC] that I&#39;m currently missing?</p></li><li><p>I want to learn from the best practitioners in [FIELD]. What do they do differently from everyone else?</p></li><li><p>Give me the diagnostic questions that reveal whether I understand [CONCEPT] or just think I understand it.</p></li><li><p>Teach me [TOPIC] in a way that will be wrong in five years versus in a way that will still be right.</p></li></ol><h2 id="category-8-productivity-and-systems-30-prompts" tabindex="-1">Category 8: Productivity and Systems (30 Prompts) <a class="header-anchor" href="#category-8-productivity-and-systems-30-prompts" aria-label="Permalink to &quot;Category 8: Productivity and Systems (30 Prompts)&quot;">​</a></h2><ol start="211"><li><p>Read my project list and tell me which one I&#39;m avoiding and what that avoidance is costing me.</p></li><li><p>I&#39;m overwhelmed. Read everything on my plate and tell me what would happen if I did nothing on each item. That determines the real priority.</p></li><li><p>Design a weekly structure for someone who does [TYPE OF WORK] that protects the highest-value work from being crowded out by urgent but unimportant tasks.</p></li><li><p>I have three hours of focused time. Tell me exactly how to use it given these constraints and objectives.</p></li><li><p>Read my workflow and identify every handoff that introduces friction or delays without adding value.</p></li><li><p>I keep not doing [TASK]. Diagnose why and give me a system that removes whatever is blocking me.</p></li><li><p>Design a capture system for someone whose best ideas come at the worst times.</p></li><li><p>I&#39;m in too many meetings. Read this calendar and tell me which ones I should stop attending, which I should delegate, and which I should redesign.</p></li><li><p>Build me a weekly review template that takes twenty minutes and actually improves the following week.</p></li><li><p>I have [GOAL] and [TIME CONSTRAINT]. Build the minimum viable system to achieve it.</p></li><li><p>Read this project and identify the critical path. What sequence of tasks determines when it finishes?</p></li><li><p>I&#39;m losing time to [RECURRING PROBLEM]. Design the system that eliminates it permanently rather than managing it repeatedly.</p></li><li><p>Design a decision log that I&#39;ll actually maintain and that will actually be useful when I look back at it in six months.</p></li><li><p>I need to delegate this effectively. Write the brief that gives someone everything they need without requiring constant check-ins.</p></li><li><p>Build me a morning routine for someone who does [TYPE OF WORK] and needs [SPECIFIC OUTCOME] before anything else competes.</p></li><li><p>I have too many priorities. Apply the constraint that only three things can be priority one and tell me which three.</p></li><li><p>Design a feedback system for [PROCESS] that catches problems early enough to fix them cheaply.</p></li><li><p>I need to make this repeatable. Read it and write the process documentation that someone else could follow without asking me questions.</p></li><li><p>Build me a project tracking system that shows me what matters without requiring constant maintenance.</p></li><li><p>I&#39;m working on [PROJECT] and getting distracted by [THING]. Design the environment and rules that make distraction less likely.</p></li><li><p>Read my task list and tell me which items are tasks and which are actually projects pretending to be tasks.</p></li><li><p>Design a weekly planning session that takes thirty minutes and makes the whole week more intentional.</p></li><li><p>I need to ship this faster without cutting corners on what matters. Tell me what corners I can actually cut.</p></li><li><p>Build me a system for processing information that keeps what&#39;s useful and discards what isn&#39;t without requiring judgment on every item.</p></li><li><p>I&#39;m bad at finishing things. Diagnose why based on what I&#39;ve told you and design the system that fixes the specific problem.</p></li><li><p>Read this goal and tell me the leading indicator that best predicts whether I&#39;ll achieve it.</p></li><li><p>Design a review process for [TYPE OF WORK] that catches the errors that matter before they cost something.</p></li><li><p>I have [RESOURCE] and [CONSTRAINT]. Tell me the highest leverage use of the resource given the constraint.</p></li><li><p>Build me a system for staying on top of [DOMAIN] without spending more than thirty minutes per week on it.</p></li><li><p>I need to build a habit around [BEHAVIOR]. Design the minimum viable implementation that has the best chance of sticking.</p></li></ol><h2 id="category-9-problem-solving-and-innovation-30-prompts" tabindex="-1">Category 9: Problem Solving and Innovation (30 Prompts) <a class="header-anchor" href="#category-9-problem-solving-and-innovation-30-prompts" aria-label="Permalink to &quot;Category 9: Problem Solving and Innovation (30 Prompts)&quot;">​</a></h2><ol start="241"><li><p>I have a problem I&#39;ve been trying to solve for [TIME]. Give me the frame I haven&#39;t tried.</p></li><li><p>Apply first principles to this problem. What&#39;s actually true versus what we&#39;ve assumed is true?</p></li><li><p>I&#39;m solving for [OUTCOME]. What&#39;s a completely different approach that would achieve the same outcome through an entirely different mechanism?</p></li><li><p>Read this problem and tell me if I&#39;m solving the right problem or a symptom of it.</p></li><li><p>What would the solution look like if we assumed the constraint I think is fixed is actually variable?</p></li><li><p>Apply [PRINCIPLE FROM COMPLETELY DIFFERENT FIELD] to this problem and tell me what it suggests.</p></li><li><p>I&#39;m stuck. Give me ten possible solutions including ones that seem too simple, too expensive, and too unconventional.</p></li><li><p>What would nature do with this problem?</p></li><li><p>Invert this. Instead of solving for [GOAL], design the system that would reliably prevent [GOAL]. Then invert that.</p></li><li><p>I need to innovate on [THING]. Tell me every assumption baked into how it currently works and which ones I could violate.</p></li><li><p>Apply the 10x constraint. If the solution had to be ten times better than the current best, what would have to be different?</p></li><li><p>What would this problem look like at ten times the scale? A hundred times? Does that suggest anything?</p></li><li><p>I&#39;m trying to optimize [THING]. What if I optimized for the opposite metric instead?</p></li><li><p>Read this constraint and tell me if it&#39;s a real constraint or a perceived one.</p></li><li><p>What would a complete outsider to this domain see about this problem that an expert would miss?</p></li><li><p>Apply the Amazon working backwards approach to this problem. Start from the ideal customer experience and work back to what that requires.</p></li><li><p>I need a creative solution. Give me one that&#39;s obvious, one that&#39;s elegant, and one that&#39;s surprising.</p></li><li><p>What&#39;s the simplest possible version of this solution that would still work?</p></li><li><p>I&#39;ve been adding to this problem. What should I subtract?</p></li><li><p>Apply the theory of constraints to this. What&#39;s the single binding constraint and what changes when I focus only on that?</p></li><li><p>What would this solution look like if it had to be free?</p></li><li><p>I&#39;m solving for [GOAL]. What are the five different mechanisms that could achieve it and what are the tradeoffs of each?</p></li><li><p>What problem is actually worth solving here that nobody has named yet?</p></li><li><p>Apply Chesterton&#39;s fence. Before I change this, make me understand why it is the way it is.</p></li><li><p>I need a breakthrough not an improvement. What&#39;s the difference in this context?</p></li><li><p>What would this look like if it worked perfectly? Describe that state in detail before designing toward it.</p></li><li><p>What&#39;s the elegant solution that&#39;s being prevented by a small assumption everyone is making?</p></li><li><p>Apply lateral thinking to this. Give me five provocations that challenge the assumptions in the problem statement.</p></li><li><p>What would I build if I knew it would work?</p></li><li><p>I need to solve this with [LIMITATION]. What does the constraint make possible that abundance wouldn&#39;t?</p></li></ol><h2 id="category-10-personal-and-professional-development-30-prompts" tabindex="-1">Category 10: Personal and Professional Development (30 Prompts) <a class="header-anchor" href="#category-10-personal-and-professional-development-30-prompts" aria-label="Permalink to &quot;Category 10: Personal and Professional Development (30 Prompts)&quot;">​</a></h2><ol start="271"><li><p>Read what I&#39;ve told you about my work and tell me the pattern in what I gravitate toward versus what I avoid.</p></li><li><p>I&#39;m trying to get better at [SKILL]. Design a 90-day plan that produces measurable improvement.</p></li><li><p>Tell me the career move I&#39;m not considering that I should be.</p></li><li><p>I&#39;m about to have a difficult conversation. Help me prepare for it by playing the other person.</p></li><li><p>What story am I telling myself about this situation that might not be true?</p></li><li><p>I want to be taken more seriously in [CONTEXT]. What specifically would need to change?</p></li><li><p>Read this situation and tell me what someone with more experience in this area would see that I&#39;m missing.</p></li><li><p>I&#39;m stuck between [OPTION A] and [OPTION B] as a career direction. Give me the framework for deciding rather than the decision.</p></li><li><p>What am I optimizing my career for that I haven&#39;t stated explicitly?</p></li><li><p>I need a mentor who doesn&#39;t exist or isn&#39;t accessible. Give me what they would tell me about this situation.</p></li><li><p>Tell me the thing I need to hear that I&#39;m probably not asking for.</p></li><li><p>I&#39;ve been working on [THING] for [TIME] and haven&#39;t made the progress I expected. Diagnose.</p></li><li><p>What would I advise someone else in exactly my situation?</p></li><li><p>I&#39;m underestimating something about this situation. Tell me what.</p></li><li><p>Design the personal board of directors I need for where I&#39;m trying to go.</p></li><li><p>What&#39;s the version of my work in five years that I&#39;d be most proud of? Now work backwards.</p></li><li><p>I need to build credibility in [DOMAIN] faster than normal. What&#39;s the path?</p></li><li><p>Tell me the professional habit that is most limiting my development based on what I&#39;ve told you.</p></li><li><p>I&#39;m about to ask for [THING]. Help me understand what I&#39;m actually asking for and whether it&#39;s what I want.</p></li><li><p>What&#39;s the investment in myself right now that would have the highest return in three years?</p></li><li><p>I&#39;m experiencing [CHALLENGE]. Tell me if this is a skill problem, a knowledge problem, a motivation problem, or an environment problem.</p></li><li><p>What would I need to believe about myself to attempt [THING I&#39;M AVOIDING]?</p></li><li><p>Design the feedback system for my own development that I&#39;ll actually use.</p></li><li><p>I want to become known for [THING]. What&#39;s the gap between where I am and where I need to be?</p></li><li><p>Tell me the thing I keep almost deciding to do that I should just decide to do.</p></li><li><p>What&#39;s the version of this situation where I&#39;m the problem?</p></li><li><p>I need to develop [QUALITY]. Give me the practice that builds it rather than the advice about why it matters.</p></li><li><p>What am I ready for that I don&#39;t think I&#39;m ready for?</p></li><li><p>Design the year that gets me closest to the professional I want to be.</p></li><li><p>Tell me what you&#39;ve noticed about how I think based on this conversation that I should know about myself.</p></li></ol><h2 id="how-to-use-these-prompts-with-fable-5" tabindex="-1">How to Use These Prompts With Fable 5 <a class="header-anchor" href="#how-to-use-these-prompts-with-fable-5" aria-label="Permalink to &quot;How to Use These Prompts With Fable 5&quot;">​</a></h2><p>The prompts above work at a different level with Fable 5 than with previous models for three specific reasons. The context window changes what&#39;s possible. Prompts in categories one and four feed entire codebases, research corpora, and document libraries as context. Previous models could not hold enough context to make those prompts work at full depth. Fable 5&#39;s million token window means the prompt and the full context fit in a single session. The honesty rate changes what&#39;s reliable. Prompts that ask Claude to challenge your assumptions, identify what you&#39;re missing, or tell you what you need to hear rather than what you want to hear depend on the model being willing to be honest. Fable 5&#39;s honesty rate dropped from 65% to under 5% for self-reporting failures. The prompts asking for genuine challenge rather than polished validation now work more reliably. The autonomous operation capability changes what&#39;s sustainable. The most powerful use of these prompts is not running them manually one at a time. It is encoding the most valuable ones as skills in Hermes Agent and having them run automatically against your vault, your projects, and your accumulated context on a schedule. Prompt 1 becomes a weekly research synthesis skill. Prompt 121 becomes a decision support skill called before any significant decision. Prompt 211 becomes a Monday morning priority review. At that point the 300 prompts are not tools you use. They are infrastructure that runs your thinking for you. That is what Fable 5 was built for. Start with the five prompts in each category that are most relevant to your current work. Run them this week. Identify the three that produce the most valuable outputs. Encode those three as skills. Build from there. Follow @cyrilXBT for every Fable 5 prompt architecture, skill template, and autonomous workflow that makes this model work at its full capability level.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：300 個針對 Fable 5 特性（百萬 token 上下文、誠實率大幅提升、自主運行能力）優化的提示詞，分 10 類，終極用法是編碼為自動執行的 SKILL 基礎設施。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>Fable 5 三大差異化能力：(1) 1M token 上下文（可吃整個 codebase/研究語料庫）；(2) 誠實率：自我報告失敗率從 65% 降至 &lt;5%；(3) 自主運行數天的能力</li><li>這 300 個 prompts 的設計前提是「利用 Fable 5 能做到但前代模型做不到的事」——並非通用提示詞</li><li><strong>最高槓桿用法</strong>：不是手動一條條跑，而是把最有價值的提示詞編碼為 Hermes Agent 的 SKILL，定時自動運行</li><li>10 個分類覆蓋：深度研究/綜合分析、撰寫與溝通、策略與決策、程式碼與技術、學習與知識提取、問題解決、創意工作、商業分析、個人思維、職業發展</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Fable 5 context window：1,000,000 tokens</li><li>誠實率改善：65% self-reporting failure rate → &lt;5%</li><li>Hermes Agent：用於將 prompts 編碼為定時自動執行的 SKILL</li><li>建議用法：每類挑 5 個，本週跑，找出輸出最有價值的 3 個，編碼為 SKILL</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>誠實率數據（65% → &lt;5%）未給出來源，是作者自己的觀察還是 Anthropic 官方 benchmark？需核實</li><li>300 個提示詞品質不均——前幾類（研究、寫作）提示詞設計紮實；後幾類（職業發展 #295-300）過於開放式，缺乏 Fable 5 特性的實際利用</li><li>「Hermes Agent」引用但未說明這是什麼工具，讀者可能無法直接複製</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>9/10</td><td>300 個即用提示詞 + 建議的 SKILL 整合路徑，直接可執行</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>提示詞本身非全新，但 Fable 5 特性對應的設計角度有參考價值</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>誠實率數據無來源，「這些 prompts 特別適合 Fable 5」的論據偏弱</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>三大差異化能力分析到位，但提示詞本身的設計原理未充分解釋</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>10 個類別覆蓋面廣，大多數知識工作者都能找到適用場景</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.0/10</strong></td><td>9×0.3+6×0.2+5×0.2+6×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：SKILL <strong>理由</strong>：總分 7.0 &gt; 6，核心是靜態提示詞集合，適合整合為可複用的 SKILL 模板庫。</p>',41)])])}const u=t(n,[["render",s]]);export{c as __pageData,u as default};
